import{_ as r,a0 as p,w as e,s as l,ao as d,I as o,x as s,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"pidstat - 監控並統計Linux進程的數據 | LCTT x X-CMD","titleTemplate":false,"description":"pidstat - 監控並統計Linux進程的數據 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"pidstat - 監控並統計Linux進程的數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"pidstat - 監控並統計Linux進程的數據 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141017 pidstat - Monitor and Find Statistics for Linux Procesess","title":"pidstat - 監控並統計Linux進程的數據","tag":"201411","desc":""},"relativePath":"201411/20141017 pidstat - Monitor and Find Statistics for Linux Procesess.md","filePath":"[post].md"}'),u={name:"201411/20141017 pidstat - Monitor and Find Statistics for Linux Procesess.md"};function g(m,t,x,c,f,h){const i=p("Link");return e(),l("div",null,[t[13]||(t[13]=d(`<h1 id="pidstat-監控並統計linux進程的數據" tabindex="-1">pidstat - 監控並統計Linux進程的數據 <a class="header-anchor" href="#pidstat-監控並統計linux進程的數據" aria-label="Permalink to “pidstat - 監控並統計Linux進程的數據”">​</a></h1><p><strong>pidstat</strong>命令用來監控被Linux內核管理的獨立任務(進程)。它輸出每個受內核管理的任務的相關信息。pidstat命令也可以用來監控特定進程的子進程。間隔參數用於指定每次報告間的時間間隔。它的值為0(或者沒有參數)説明進程的統計數據的時間是從系統啓動開始計算的。</p><h3 id="如何安裝pidstat" tabindex="-1">如何安裝pidstat <a class="header-anchor" href="#如何安裝pidstat" aria-label="Permalink to “如何安裝pidstat”">​</a></h3><p>pidstat 是sysstat軟件套件的一部分，sysstat包含很多監控linux系統狀態的工具，它能夠從大多數linux發行版的軟件源中獲得。</p><p>在Debian/Ubuntu系統中可以使用下面的命令來安裝</p><pre><code># apt-get install sysstat
</code></pre><p>CentOS/Fedora/RHEL版本的linux中則使用下面的命令：</p><pre><code># yum install sysstat
</code></pre><h3 id="使用pidstat" tabindex="-1">使用pidstat <a class="header-anchor" href="#使用pidstat" aria-label="Permalink to “使用pidstat”">​</a></h3><p>使用pidstat不加任何參數等價於加上-p參數，但是隻有正在活動的任務會被顯示出來。</p><pre><code># pidstat
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/pidstat.jpg" alt="pidstat"></p><p>在結果中你能看到如下內容：</p><ul><li><strong>PID</strong> - 被監控的任務的進程號</li><li><strong>%usr</strong> - 當在用户層執行(應用程序)時這個任務的cpu使用率，和 nice 優先級無關。注意這個字段計算的cpu時間不包括在虛擬處理器中花去的時間。</li><li><strong>%system</strong> - 這個任務在系統層使用時的cpu使用率。</li><li><strong>%guest</strong> - 任務花費在虛擬機上的cpu使用率（運行在虛擬處理器）。</li><li><strong>%CPU</strong> - 任務總的cpu使用率。在SMP環境(多處理器)中，如果在命令列中輸入-I參數的話，cpu使用率會除以你的cpu數量。</li><li><strong>CPU</strong> - 正在運行這個任務的處理器編號。</li><li><strong>Command</strong> - 這個任務的命令名稱。</li></ul><h3 id="i-o-統計數據" tabindex="-1">I/O 統計數據 <a class="header-anchor" href="#i-o-統計數據" aria-label="Permalink to “I/O 統計數據”">​</a></h3><p>通過使用-d參數來得到I/O的統計數據。比如：</p><pre><code># pidstat -d -p 8472
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/pidstat-io.jpg" alt="pidstat io"></p><p>IO 輸出會顯示一些內的條目：</p><ul><li><strong>kB_rd/s</strong> - 任務從硬盤上的讀取速度（kb）</li><li><strong>kB_wr/s</strong> - 任務向硬盤中的寫入速度（kb）</li><li><strong>kB_ccwr/s</strong> - 任務寫入磁盤被取消的速率（kb）</li></ul><h3 id="頁面失敗和內存使用" tabindex="-1">頁面失敗和內存使用 <a class="header-anchor" href="#頁面失敗和內存使用" aria-label="Permalink to “頁面失敗和內存使用”">​</a></h3><p>使用-r標記你能夠得到內存使用情況的數據。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/pidstat-pfmem.jpg" alt="pidstat pf mem"></p><p>重要的條目：</p><ul><li><strong>minflt/s</strong> - 從內存中加載數據時每秒出現的小的錯誤的數目，這些不要求從磁盤載入內存頁面。</li><li><strong>majflt/s</strong> - 從內存中加載數據時每秒出現的較大錯誤的數目，這些要求從磁盤載入內存頁面。</li><li><strong>VSZ</strong> - 虛擬容量：整個進程的虛擬內存使用（kb）</li><li><strong>RSS</strong> - 長期內存使用：任務的不可交換物理內存的使用量（kb）</li></ul><h3 id="舉例" tabindex="-1">舉例 <a class="header-anchor" href="#舉例" aria-label="Permalink to “舉例”">​</a></h3><p><strong>1.</strong> 你可以通過使用下面的命令來監測內存使用</p><pre><code># pidstat -r 2 5
</code></pre><p>這會給你5份關於page faults的統計數據結果，間隔2秒。這將會更容易的定位出現問題的進程。</p><p><strong>2.</strong> 顯示所有mysql服務器的子進程</p><pre><code># pidstat -T CHILD -C mysql
</code></pre><p><strong>3.</strong> 將所有的統計數據結合到一個便於閲讀的單一報告中：</p><pre><code># pidstat -urd -h
</code></pre><hr>`,34)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),a(i,{href:"http://linoxide.com/linux-command/linux-pidstat-monitor-statistics-procesess/"},{default:n(()=>[...t[0]||(t[0]=[s("http://linoxide.com/linux-command/linux-pidstat-monitor-statistics-procesess/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=s("作者：",-1)),a(i,{href:"http://linoxide.com/author/adriand/"},{default:n(()=>[...t[2]||(t[2]=[s("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=s(" 譯者：",-1)),a(i,{href:"https://github.com/johnhoow"},{default:n(()=>[...t[3]||(t[3]=[s("John",-1)])]),_:1}),t[7]||(t[7]=s(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原創翻譯，",-1)),a(i,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[s("Linux中國",-1)])]),_:1}),t[12]||(t[12]=s(" 榮譽推出",-1))])])}const C=r(u,[["render",g]]);export{T as __pageData,C as default};
